async () => {
  await withWindowsSandbox("asset-enumerate-denied", async (sandbox) => {
    await prepare(sandbox.workspaceRoot, ["Broken", "Missing"]);
    const directory = join(sandbox.workspaceRoot, "Game/img/pictures");
